function ProductList() {
  const [isLoading, setIsLoading] = useState(true)
  const [products, setProducts] = useState([])

  useEffect(() => {
    fetch('/api/products')
      .then(res => res.json())
      .then(data => {
        setProducts(data)
        setIsLoading(false)
      })
  }, [])

  if (isLoading) return <ActivityIndicator />
  return <ProductGrid products={products} />
}
